"use client";

import {
    Store,
    Plus,
    Share2,
    ExternalLink,
    QrCode,
    Edit3,
    Copy,
    Tag,
    CircleDollarSign,
    Package,
    Layers,
    Trash2
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useState } from "react";
import { fetcher } from "@/lib/fetcher";
import useSWR, { mutate } from "swr";
import { useSimulation } from "@/components/SimulationProvider";
import axios from "axios";
import ProductModal from "@/components/ProductModal";

export default function LojaPage() {
    const { currentUser } = useSimulation();
    const { data: products, error } = useSWR("/api/sales", fetcher);
    const [activeTab, setActiveTab] = useState("Todos");

    // Management state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedProduct, setSelectedProduct] = useState<any>(null);
    const [modalTitle, setModalTitle] = useState("Novo Produto");

    const isAdmin = currentUser.role === "admin";

    const handleAdd = () => {
        setSelectedProduct(null);
        setModalTitle("Novo Produto");
        setIsModalOpen(true);
    };

    const handleEdit = (product: any) => {
        setSelectedProduct(product);
        setModalTitle("Editar Produto");
        setIsModalOpen(true);
    };

    const handleDelete = async (id: any) => {
        if (confirm("Tem certeza que deseja excluir este produto do catálogo?")) {
            await axios.delete(`/api/sales?id=${id}`);
            mutate("/api/sales");
        }
    };

    const handleModalSubmit = async (data: any) => {
        if (selectedProduct) {
            await axios.put("/api/sales", { ...data, id: selectedProduct.id });
        } else {
            await axios.post("/api/sales", data);
        }
        setIsModalOpen(false);
        mutate("/api/sales");
    };

    return (
        <div className="p-4 lg:p-8 space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-black mb-1">Links de Venda</h1>
                    <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Catálogo de Produtos e Links Diretos</p>
                </div>
                {isAdmin && (
                    <button
                        onClick={handleAdd}
                        className="bg-primary text-white px-6 py-2.5 rounded-xl font-bold text-xs flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-[1.02] transition-all self-start md:self-auto"
                    >
                        <Plus size={16} />
                        Novo Produto
                    </button>
                )}
            </div>

            {/* Categories */}
            <div className="flex items-center gap-2 overflow-x-auto pb-2 custom-scrollbar">
                {["Todos", "CPF", "CNPJ", "Específicos"].map((category) => (
                    <button
                        key={category}
                        onClick={() => setActiveTab(category)}
                        className={cn(
                            "px-5 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center gap-2 whitespace-nowrap",
                            activeTab === category
                                ? "bg-primary text-white shadow-lg shadow-primary/20"
                                : "bg-white dark:bg-slate-800 text-slate-500 border border-slate-200 dark:border-slate-800 hover:border-primary"
                        )}
                    >
                        {category === "Todos" && <Layers size={14} />}
                        {category === "CPF" && <Tag size={14} />}
                        {category === "CNPJ" && <Package size={14} />}
                        {category === "Específicos" && <Store size={14} />}
                        {category}
                    </button>
                ))}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {!products && !error && <p className="col-span-full text-center text-slate-400 py-20 italic">Carregando catálogo...</p>}
                {(products || []).filter((p: any) => activeTab === "Todos" || p.category === activeTab).map((product: any) => (
                    <div key={product.id} className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm hover:shadow-md transition-shadow flex flex-col group">
                        <div className="p-6 flex-1">
                            <div className="flex justify-between items-start mb-6">
                                <div className="size-12 rounded-2xl bg-primary/10 flex items-center justify-center text-primary">
                                    <Package size={24} />
                                </div>
                                <div className="text-right flex flex-col items-end">
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Preço Sugerido</p>
                                    <p className="text-xl font-black text-slate-900 dark:text-white">
                                        {product.price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                    </p>

                                    {isAdmin && (
                                        <div className="flex gap-1 mt-2 transition-opacity opacity-0 group-hover:opacity-100">
                                            <button
                                                onClick={() => handleEdit(product)}
                                                className="p-1.5 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg"
                                            >
                                                <Edit3 size={14} />
                                            </button>
                                            <button
                                                onClick={() => handleDelete(product.id)}
                                                className="p-1.5 text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg"
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>

                            <h3 className="text-lg font-bold mb-1">{product.name}</h3>
                            <div className="flex items-center gap-2 mb-6">
                                <span className="px-2 py-0.5 bg-slate-100 dark:bg-slate-700 rounded text-[9px] font-bold text-slate-500 uppercase">{product.category}</span>
                                <span className="px-2 py-0.5 bg-blue-50 dark:bg-blue-900/20 rounded text-[9px] font-bold text-blue-600 uppercase">{product.type}</span>
                            </div>

                            <div className="bg-slate-50 dark:bg-slate-900/50 rounded-2xl p-4 flex items-center justify-between mb-6">
                                <div>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Sua Comissão</p>
                                    <p className="text-sm font-black text-emerald-500">
                                        {product.commission.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                                    </p>
                                </div>
                                <div className="h-8 w-px bg-slate-200 dark:bg-slate-800"></div>
                                <div>
                                    <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Margem</p>
                                    <p className="text-sm font-black text-indigo-500">
                                        {(product.commission / product.price * 100).toFixed(0)}%
                                    </p>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-3 pb-4 border-b border-slate-50 dark:border-slate-800">
                                <button className="flex items-center justify-center gap-2 py-2.5 bg-primary text-white rounded-xl text-[10px] font-bold hover:scale-[1.02] transition-all">
                                    <Copy size={14} />
                                    Copiar Link
                                </button>
                                <button className="flex items-center justify-center gap-2 py-2.5 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl text-[10px] font-bold hover:bg-slate-200 transition-all">
                                    <QrCode size={14} />
                                    QR Code
                                </button>
                            </div>

                            <div className="flex items-center justify-between pt-4 mt-auto">
                                <button className="text-[10px] font-bold uppercase tracking-wider text-slate-400 hover:text-primary transition-colors flex items-center gap-1.5">
                                    <Edit3 size={12} />
                                    Customizar
                                </button>
                                <div className="flex gap-2">
                                    <button className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg text-slate-400">
                                        <Share2 size={16} />
                                    </button>
                                    <button className="p-1.5 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg text-slate-400">
                                        <ExternalLink size={16} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            <ProductModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                onSubmit={handleModalSubmit}
                initialData={selectedProduct}
                title={modalTitle}
            />
        </div>
    );
}
